INSERT INTO quizzes (id, course_id, title, description, passing_score, duration_minutes, quiz_category, difficulty_level, quiz_sequence)
INSERT INTO quiz_questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, order_number)
VALUES
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'A customer brings you an electric kettle that has stopped heating. What must you do BEFORE you open the base and start testing?', 'multiple_choice', '{"A": "Switch the kettle off at its own on/off switch and leave it plugged in", "B": "Switch off the wall socket but leave the plug in, so the earth stays connected", "C": "Unplug it completely from the socket, then confirm with a tester that no voltage is present", "D": "Fill it with water first so the element does not burn out during testing"}'::jsonb, 'C', 'Full isolation means physically removing the plug so no live conductor can reach the appliance, and then proving it dead with a tester rather than trusting a switch. Switches and sockets can be wired wrongly or faulty, so ''switched off'' is never proof of ''safe''.', 1),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'Domestic mains supply in most African countries is nominally:', 'multiple_choice', '{"A": "110-120 V at 60 Hz", "B": "220-240 V at 50 Hz", "C": "12-24 V DC", "D": "380-415 V single phase at 50 Hz"}'::jsonb, 'B', 'Household supply across most of Africa is single-phase 220-240 V at 50 Hz, so replacement motors, elements and lamps must be rated for that. 380-415 V is the three-phase (line-to-line) voltage used for larger machines, not a normal wall socket.', 2),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'What is the main job of the earth (ground) wire in a metal-bodied appliance such as a washing machine?', 'multiple_choice', '{"A": "It carries the normal working current back to the supply instead of the neutral", "B": "It reduces the electricity bill by returning unused current", "C": "It stops the motor from vibrating on a concrete floor", "D": "If a live wire touches the metal body, it gives fault current a low-resistance path so the fuse or breaker trips instead of the casing staying live"}'::jsonb, 'D', 'The earth conductor is a safety path: a live-to-casing fault becomes a large fault current that blows the fuse or trips the breaker within a fraction of a second. Without a good earth the casing simply sits at mains voltage waiting for someone to touch it.', 3),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'In modern harmonised appliance flex, which colour identifies the earth conductor?', 'multiple_choice', '{"A": "Green with a yellow stripe", "B": "Solid blue", "C": "Brown", "D": "Black"}'::jsonb, 'A', 'Green/yellow is reserved worldwide for protective earth and must never be used for any other purpose; brown is live and blue is neutral in the same flex. Older cords may use green, red and black, so always confirm with a meter rather than assuming.', 4),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'You have unplugged a microwave oven and removed the outer cover. Before touching anything inside, what specific hazard must you deal with?', 'multiple_choice', '{"A": "Residual microwave radiation trapped inside the cavity", "B": "The high-voltage capacitor, which can hold a lethal charge even with the oven unplugged, and must be discharged through a resistor or insulated screwdriver blade across its terminals", "C": "The turntable motor, which can restart on its own", "D": "Hot oil residue on the magnetron fins"}'::jsonb, 'B', 'The HV capacitor in a microwave stores enough energy to kill and does not necessarily bleed down when unplugged, especially if its internal bleeder resistor has failed. Always short both terminals to each other and to chassis, then confirm 0 V with a meter, before your hands go inside.', 5),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'You want to check whether the heating element of an iron has gone open circuit. Which meter setting and condition is correct?', 'multiple_choice', '{"A": "AC volts, with the iron plugged in and switched on", "B": "DC volts, with the iron plugged in and heating", "C": "Ohms (resistance) or continuity, with the iron unplugged and the element leads disconnected", "D": "AC amps clamped around the flex while the iron is running"}'::jsonb, 'C', 'Resistance and continuity tests use the meter''s own tiny test current, so the circuit must be dead or you will damage the meter and risk a shock. Disconnecting one element lead also stops other parallel components giving you a false reading.', 6),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'A fridge has an interior light that works and a cabinet that stays warm, and you hear no compressor sound at all. Which fault group should you check FIRST?', 'multiple_choice', '{"A": "The refrigerant charge, since the gas has clearly leaked out", "B": "The door gasket, since warm air is leaking in", "C": "The evaporator fan blades", "D": "The thermostat, start relay and overload protector that supply the compressor"}'::jsonb, 'D', 'The light proves mains is reaching the appliance, so the problem lies between that supply and the compressor: thermostat, start relay/PTC or overload. A gas leak would normally show a compressor that runs continuously without cooling, not a silent one.', 7),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'You measure the three terminals of a fridge compressor: Common-Start, Common-Run and Start-Run. In a healthy single-phase compressor, which statement is true?', 'multiple_choice', '{"A": "Start-Run reads the highest, and equals Common-Start plus Common-Run added together", "B": "All three readings should be identical", "C": "Common-Run should read the highest of the three", "D": "Any terminal to the metal shell should read a few ohms"}'::jsonb, 'A', 'The two windings are in series across Start and Run, so C-S + C-R = S-R, with the start winding having the higher resistance of the two. Any low reading from a terminal to the shell means a winding is shorted to earth and the compressor is scrap.', 8),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'Testing a kettle element on the ohms range, your meter shows ''OL'' (over-limit / infinity). What does this mean?', 'multiple_choice', '{"A": "The element is shorted and drawing too much current", "B": "The element is open circuit (broken) and must be replaced", "C": "The element is in perfect condition", "D": "The meter battery is flat"}'::jsonb, 'B', 'A working element is a continuous resistance wire and reads a definite value, so infinite resistance means the path is broken. A short would show near zero ohms instead, and you can prove the meter is fine by touching the probes together first.', 9),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'A top-loading washing machine fills and washes but will not drain, and the drum stays full of water. What is the most sensible first check?', 'multiple_choice', '{"A": "Replace the main control board", "B": "Replace the drive motor", "C": "Clear the drain pump filter and check the drain hose for a blockage or a kink", "D": "Top up the machine with more water to build pressure"}'::jsonb, 'C', 'Coins, hair, buttons and lint blocking the pump filter or a kinked hose cause far more no-drain calls than electronic failures, and clearing them costs nothing but time. Always exhaust cheap mechanical causes before condemning an expensive board.', 10),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'Many newer fridges carry a warning label reading ''R600a''. What does this mean for how you work on them?', 'multiple_choice', '{"A": "The refrigerant is isobutane, which is flammable, so no naked flame, no smoking and no sparking tools near the sealed system, and the area must be well ventilated", "B": "The refrigerant is non-flammable, so brazing can be done anywhere", "C": "It means the fridge runs on 600 watts", "D": "It means the compressor is a 600 mm long linear type"}'::jsonb, 'A', 'R600a is isobutane, a hydrocarbon that burns readily, so any leak plus a flame, spark or hot soldering iron becomes a fire risk. Charges are small, but you still ventilate the room and use the correct spark-free procedure before opening the sealed system.', 11),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'What does an RCD (residual current device, sometimes called an ELCB or earth leakage unit) actually protect against?', 'multiple_choice', '{"A": "Lightning strikes on the incoming line", "B": "Overloading the circuit with too many appliances", "C": "Low voltage damaging motors", "D": "Current leaking to earth, for example through a person, tripping fast enough to reduce the risk of fatal electric shock"}'::jsonb, 'D', 'An RCD compares live and neutral current and trips when the difference exceeds a small threshold, which is what happens when current escapes through a body or damp insulation. Overload and short-circuit protection is the job of the fuse or MCB, which is a different device.', 12),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'A ceiling fan (or a washer motor) hums when switched on but the shaft does not turn, and it starts if you spin the blade by hand. The most likely cause is:', 'multiple_choice', '{"A": "The mains voltage is too high", "B": "A failed start/run capacitor", "C": "The switch contacts are welded closed", "D": "The earth wire has come loose"}'::jsonb, 'B', 'The capacitor creates the phase shift that gives a single-phase motor its starting torque; without it the motor only hums and can be nudged into rotation by hand. Leaving it running in that state overheats the winding, so switch off immediately and replace the capacitor.', 13),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'You test a motor capacitor marked 8 uF with a meter on the capacitance range and read 5.2 uF. What should you do?', 'multiple_choice', '{"A": "Accept it, since any reading at all means it works", "B": "Fit it anyway but on a lower voltage supply", "C": "Replace it with one of the same microfarad rating and at least the same voltage rating, because it has lost far more capacitance than the permitted tolerance", "D": "Recharge it from the mains to restore the missing microfarads"}'::jsonb, 'C', 'Motor capacitors are typically within about 5-10% of their marked value when healthy, so a drop of a third means it is worn out and starting torque will be weak. The replacement must match the uF value and have a voltage rating equal to or higher than the original, never lower.', 14),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'A customer phones and asks ''how much to fix my fridge?'' before you have seen it. What is the most professional and profitable response?', 'multiple_choice', '{"A": "Explain that you charge a set call-out/diagnosis fee, inspect the appliance, then give a written quote for the repair before any parts are bought or work begins", "B": "Give the lowest possible price over the phone to make sure you win the job", "C": "Refuse to discuss money until the repair is finished", "D": "Quote a very high figure so you can reduce it later"}'::jsonb, 'A', 'You cannot price a repair you have not diagnosed, and a phone guess either loses you money or forces an awkward increase later. A stated diagnosis fee pays for your time and transport, and a written quote agreed in advance prevents disputes over the final bill.', 15),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'You are setting the price for a repair job in your new business. Which basis is sound?', 'multiple_choice', '{"A": "Whatever the customer says they can afford on the day", "B": "The price of a brand new appliance, minus a small discount", "C": "Only the cost of the spare part, since the labour is your own time and costs you nothing", "D": "Cost of parts, plus your labour time, plus transport and consumables, plus a margin for tools, warranty returns and profit"}'::jsonb, 'D', 'Your time, fuel, solder, cable ties and the occasional job you must redo under warranty are all real costs that must be recovered or the business slowly consumes itself. Pricing on parts alone is the most common reason small repair businesses stay busy but never grow.', 16),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'A tumble dryer (or a hot plate) is dead because its thermal fuse has blown. What is the correct action?', 'multiple_choice', '{"A": "Bridge the thermal fuse with a piece of wire so the machine works again", "B": "Fit a new thermal fuse of the same rating AND find and fix why it overheated, such as blocked lint filters, a clogged vent or a failed thermostat", "C": "Fit a thermal fuse with a much higher temperature rating so it will not blow again", "D": "Reset the thermal fuse by letting it cool for an hour"}'::jsonb, 'B', 'A thermal fuse is a one-shot safety device that opens because something made the appliance too hot, so replacing it without curing the cause simply sets up the next failure or a fire. Bridging or over-rating it removes the protection entirely and makes you liable for the consequences.', 17),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'An electric iron works intermittently: it heats, then dies, and heating returns if the customer wiggles the cord near the iron. What is the most probable fault?', 'multiple_choice', '{"A": "The thermostat has failed permanently open", "B": "The soleplate is warped", "C": "A broken conductor or loose connection in the flex where it enters the iron, at the point of repeated flexing and strain", "D": "The mains socket is undersized for the iron''s wattage"}'::jsonb, 'C', 'Repeated bending at the cord entry work-hardens and fractures the copper strands, so contact comes and goes with movement, which is exactly the wiggle-sensitive symptom described. Cut back the damaged section and re-terminate with the strain relief properly clamped, or replace the flex.', 18),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'After repairing a metal-cased appliance, you carry out an insulation resistance test with an insulation tester between the joined live and neutral pins and the earth pin. Which result indicates the appliance is safe to return?', 'multiple_choice', '{"A": "A high resistance, of the order of 1 megohm or more", "B": "Around 50 ohms", "C": "Zero ohms, showing good continuity", "D": "Any reading is acceptable as long as the appliance runs"}'::jsonb, 'A', 'This test checks that the current-carrying parts are well insulated from the casing, so you want a very high resistance; a low value means moisture, carbon tracking or a damaged winding is leaking to earth. A separate earth continuity test is the opposite case, where you do want a near-zero reading between the earth pin and the metal body.', 19),
(gen_random_uuid(), (SELECT id FROM quizzes WHERE course_id='84d4df93-67e6-448c-8c01-6538b9dddad4' AND quiz_sequence=1), 'A fridge runs constantly, the compressor is warm and running, but nothing gets cold and there is no frost on the evaporator. You suspect the refrigerant has leaked. What is the correct professional handling?', 'multiple_choice', '{"A": "Puncture the pipe and add gas from a small can until it cools again", "B": "Treat it as sealed-system work: locate and repair the leak, evacuate the system properly, then charge the correct refrigerant type by weight, using the right equipment and skills, or refer the job to someone who has them", "C": "Replace the thermostat, since that is the usual cause", "D": "Tell the customer the fridge is beyond repair and should be scrapped"}'::jsonb, 'B', 'Gas does not get used up, so an empty system means a leak that will simply empty again unless it is found and fixed, and a system opened to air and moisture must be evacuated before recharging or it will block at the capillary. Charging a domestic fridge is done by weight to the figure on the rating plate, not by guesswork or by feel.', 20);
